INSERT INTO StudyMaterials (subject_id, chapter_number, chapter_name, topic_number, topic_name, introduction, basic_concept) VALUES (35, 1, N'Fundamentals of C Programming', 1, N'Data Types and Variables', N'<p>In C Programming, variables are named storage locations in memory. Every variable must have a defined data type that informs the compiler how much memory space to allocate and how to interpret the binary values stored within it.</p>', N'<p>Variable naming rules in C: Names can contain letters, digits, and underscores, but MUST start with a letter or underscore. Keywords (reserved terms like <code>return</code>, <code>if</code>, <code>while</code>) cannot be used as variable names.</p>
INSERT INTO StudyMaterials (subject_id, chapter_number, chapter_name, topic_number, topic_name, introduction, basic_concept) VALUES (35, 2, N'Control Flow Statements', 1, N'Loops', N'<p>Loops allow code blocks to execute repeatedly based on boolean conditional evaluations, which is a core construct in algorithm designs.</p>', N'<p>Loops depend on loop-control variables. In C, any non-zero value evaluates as true, while zero evaluates as false.</p>
INSERT INTO StudyMaterials (subject_id, chapter_number, chapter_name, topic_number, topic_name, introduction, basic_concept) VALUES (1, 1, N'Sets and Cardinality', 1, N'Venn Diagrams', N'<p>Venn diagrams, introduced by John Venn in 1880, represent set relationships using closed shapes, typically circles inside a rectangle denoting the universal set.</p>', N'<p>The region of intersection (overlapping area) represents common elements: <code>A ∩ B</code>. The entire circle area combined represents the union: <code>A U B</code>.</p>
